import type { Law } from './types';

export const LAWS: Law[] = [
  /* ---------------- 13 ---------------- */
  {
    n: 13, id: 'self-interest', title: 'When Asking for Help, Appeal to People’s Self-Interest, Never to Their Mercy or Gratitude', realm: 'lure',
    line: 'Don’t ask people to remember what they owe you. Show them what they stand to gain.',
    gist: 'When you need something from someone powerful, the law says, reminding them of past favours or begging for pity is the weakest card you can play. Gratitude feels like a debt, and people resent debts; pity puts you below them and invites contempt. Show instead how helping you serves their own aims, and the request stops being a burden and becomes an opportunity. Greene’s point is that self-interest is the one motive you can rely on, because it never needs reminding.',
    scene: { who: 'Corcyra, Corinth and Athens', when: '433 BC', text: 'Corcyra and Corinth were heading for war, and both sent envoys to Athens to win its support. Thucydides records the two speeches. The Corinthians leaned on the past: they had done Athens good turns and asked to be repaid in kind. The Corcyraeans barely mentioned favours at all. They pointed to their fleet, one of the largest in Greece, and argued that a war with Sparta was coming and Athens would want those ships on its side, not Corinth’s. Athens agreed a defensive alliance with Corcyra.' },
    mind: 'Humans keep a rough mental ledger of who owes whom, and being in debt is uncomfortable: it signals lower status and limits freedom. So a reminder of gratitude often triggers quiet resistance rather than generosity. Pity works for close kin and in small doses, but compassion fatigues quickly, and a plea for mercy marks the asker as dependent. A request framed as mutual gain, by contrast, lets the helper keep their sense of autonomy and status. They are not giving something away; they are making a smart move. It also helps that people tend to assume others run on self-interest, so a request that speaks that language feels honest and easy to grant.',
    levers: [
      { name: 'Indebtedness aversion', text: 'Martin Greenberg’s theory of indebtedness holds that owing someone creates tension people want to discharge, sometimes by avoiding the creditor. Reminding a powerful person of a past favour presses on that sore spot rather than warming them up.' },
      { name: 'Norm of self-interest', text: 'Dale Miller showed that Western cultures carry a strong belief that people act from self-interest, and that people often explain even generous acts in selfish terms. A request that offers a payoff fits that script and needs no further justification.' },
      { name: 'Motivation crowding', text: 'Rewards and moral motives don’t simply add up: putting a price on something can push out the sense of duty. This cuts both ways for the law. It explains why mutual-gain framing works with strangers and rivals, and why it can cheapen a request between friends.' },
    ],
    traps: [
      { id: 'framing', how: 'The same favour can be described as a sacrifice or as an investment. The law chooses the frame in which saying yes looks like the clever, self-serving choice.' },
      { id: 'loss-aversion', how: 'Cast as “what you’ll miss if you don’t”, a request lands harder than a plea for kindness. People work harder to avoid a loss than to secure an equal gain.' },
      { id: 'optimism', how: 'Promised returns are rarely guaranteed, but the helper tends to picture the rosy version of the deal. The asker only needs the gain to look likely, not to be certain.' },
    ],
    study: { who: 'Uri Gneezy and Aldo Rustichini, 2000', title: 'A fine is a price', text: 'Ten day-care centres in Haifa had a problem with parents collecting their children late. In six of them, the researchers introduced a small fine for lateness. Late pickups did not fall: they rose sharply, and stayed high even after the fine was removed. A moral obligation to the staff had turned into a transaction, and parents now simply weighed the cost, which shows how much the frame of a request decides how people respond.' },
    today: [
      'Pitching to an investor by talking about their portfolio, not your dream',
      'Asking a busy colleague for help by showing how it advances their project',
      'Networking messages that open with what you can offer, not what you need',
      'Politicians courting a bloc by naming what it gains, not what it owes the party',
    ],
    scenario: 'Mira needs a senior engineer from another team for two weeks. Instead of reminding the team lead that she covered for him last spring, she explains that the work will give his team a component they have wanted for a year, and that his name will be on the launch.',
    signs: [
      'A request arrives already dressed as a favour to you',
      'The benefits to you are vivid, while the costs are vague or deferred',
      'You feel clever for agreeing, rather than kind',
      'The asker never mentions what they get out of it',
    ],
    defense: [
      'Ask plainly what the other person gains, and weigh it next to your share',
      'Separate the real benefit from the flattering picture of it',
      'Get promised returns in writing, with dates',
      'Notice when a pure transaction is quietly replacing a relationship you value',
    ],
    shadow: 'Treat every relationship as a trade and people learn to treat you the same way: they help exactly as far as it pays, and not an inch further. Friends and family can feel insulted when a request is pitched like a deal. Genuine need, openly stated, can draw out loyalty that no bargain would buy. With people who care about you, honesty about what you need is often the stronger appeal.',
    honest: 'When you ask for help, think about the other person’s position and show them honestly where the request fits their goals. That is respect, not manipulation. Just don’t invent gains that aren’t there, and don’t be afraid to simply ask.',
    question: 'When you last asked for help, did you think about what the other person would get from saying yes?',
    dark: 3, everyday: 8, kin: [7, 11, 43],
  },

  /* ---------------- 14 ---------------- */
  {
    n: 14, id: 'spy', title: 'Pose as a Friend, Work as a Spy', realm: 'mask',
    line: 'The friendliest listener in the room may be the one taking notes.',
    gist: 'Knowing what your rivals want, fear and plan is worth more than almost any other advantage, and the best source is the rival themselves. The law says to gather that knowledge through warmth: dinners, confidences, easy conversation in which the other person relaxes and talks. People guard their secrets against enemies, not friends. Greene argues that a relaxed mind leaks, and that a skilled listener can learn more over a meal than a spy could by stealing letters.',
    scene: { who: 'Kim Philby and James Angleton', when: '1949–1951', text: 'Kim Philby arrived in Washington as the British intelligence liaison to the CIA and FBI. He became close to James Angleton, a rising CIA officer, and the two met for long, boozy lunches where they talked shop freely. All the while Philby was a Soviet agent, passing what he learned to Moscow. When his fellow spies Burgess and Maclean fled in 1951, suspicion fell on him and he was recalled, though he did not defect until 1963. Angleton, who had trusted him as a friend, spent much of his later career hunting moles with a suspicion that some colleagues came to see as obsessive.' },
    mind: 'Friendship lowers our guard because our ancestors could not survive by suspecting everyone in their band. Once someone is coded as an ally, the brain switches from vigilance to openness, and sharing personal details feels like bonding rather than exposure. Talking about ourselves is also pleasurable in its own right, so a good listener is giving us a small reward each time we disclose. Disclosure tends to be matched, so a friend who confides a little invites us to confide more. And the warm feeling of being understood makes it hard to imagine that the same person might use what they heard.',
    levers: [
      { name: 'Self-disclosure reciprocity', text: 'People tend to match the intimacy of what others tell them. A spy who offers a small, safe confession invites a larger, riskier one in return.' },
      { name: 'Similarity-attraction', text: 'We like people who seem to share our views, background and tastes. Mirroring a target’s opinions buys trust quickly, and trust opens the conversation.' },
      { name: 'Ingratiation', text: 'Edward Jones described ingratiation as a set of tactics, such as flattery, agreement and favours, used to make someone like you. Its purpose here is access: liking is the door, information is what lies behind it.' },
      { name: 'The reward of talking about yourself', text: 'Neuroscience suggests that disclosing personal thoughts activates the brain’s reward circuitry. An attentive listener feeds that appetite, and people keep talking.' },
    ],
    traps: [
      { id: 'halo', how: 'A friend’s warmth spills over into a judgement of their honesty. Because they are pleasant company, it doesn’t occur to you that they could be working an angle.' },
      { id: 'in-group', how: 'Once someone is filed as “one of us”, their questions feel like shared interest rather than probing. The spy’s first job is to get inside your circle.' },
      { id: 'projection', how: 'You assume the friend is as open with you as you are with them. In fact the flow of information may run almost entirely one way.' },
    ],
    study: { who: 'Nancy Collins and Lynn Carol Miller, 1994', title: 'Self-disclosure and liking', text: 'Collins and Miller pooled the research on confiding and liking and found three separate effects. People who disclose more intimate things tend to be liked more. People disclose more to those they already like. And people come to like someone more after confiding in them. The last is the spy’s door: a warm listener who draws out your secrets becomes, in your own eyes, a friend, because you have trusted them. Later reviewers noted that only a handful of studies had tested that third effect directly, so it is the least certain of the three, but it fits Angleton’s long lunches with Philby uncomfortably well.' },
    today: [
      'A new colleague who befriends you fast and asks a lot about your manager',
      'Competitors who meet for “coffee, no agenda” and leave with your roadmap',
      'A date who asks probing questions but stays vague about themselves',
      'Recruiters and journalists who build rapport before the real question',
    ],
    scenario: 'At a conference, a friendly rival invites Sam to dinner, buys the wine and tells a funny story about his own company’s failures. By dessert Sam has explained his firm’s pricing plans and the client they are about to lose.',
    signs: [
      'The warmth arrived quickly and the questions arrived soon after',
      'You leave conversations having said far more than you learned',
      'Their stories about themselves are charming but never specific',
      'They keep circling back to one topic you know is sensitive',
    ],
    defense: [
      'Keep a mental line between what you share with friends and what you share at work',
      'Notice the ratio: if you’re doing most of the confiding, slow down',
      'Answer specific questions with general answers and see if they push',
      'Be careful with alcohol and late nights around people with a stake in your plans',
    ],
    shadow: 'Spying on friends poisons the well. Once discovered, the betrayal is remembered far longer than any information it yielded, and the spy is shut out of every circle that hears of it. Living this way also means you can never fully relax, because you know how easily confidences are taken. Real friendship, kept clean, often gives you better information over time than a fake one, because people volunteer what they would never let slip.',
    honest: 'Curiosity about other people, and listening more than you speak, is simply good sense. The line is intention: learn about people to understand and work with them, not to use their trust against them, and be honest about the role you are in.',
    question: 'Who in your life learns more from you than you learn from them, and do you know why?',
    dark: 7, everyday: 6, kin: [2, 3, 33, 38],
  },

  /* ---------------- 15 ---------------- */
  {
    n: 15, id: 'crush', title: 'Crush Your Enemy Totally', realm: 'war',
    line: 'An enemy left standing is an enemy who will return.',
    gist: 'The law says that when you have a dangerous rival at your mercy, half measures are a mistake. A wounded enemy remembers the wound, recovers, and comes back with a grudge and a lesson learned. Mercy at the wrong moment is read as weakness or indecision. Greene argues that total victory ends the matter, while partial victory only postpones the next round on worse terms.',
    scene: { who: 'Xiang Yu, Liu Bang and the adviser Fan Zeng', when: '206–202 BC', text: 'After the fall of the Qin, the warlord Xiang Yu invited his rival Liu Bang to a feast at Hong Gate. His adviser Fan Zeng had urged him to kill Liu Bang there, and during the banquet a sword dance was staged as cover for an assassination. Xiang Yu hesitated, a relative shielded Liu Bang, and the guest slipped away on the pretext of visiting the latrine. Four years of war followed. At Gaixia in 202 BC Xiang Yu was surrounded and defeated, and he took his own life. Liu Bang founded the Han dynasty.' },
    mind: 'Humiliation is one of the strongest motives people have. Defeat that leaves someone alive but shamed creates a need to restore status, and the brain treats unfinished conflicts as open loops that keep demanding attention. Revenge is also rewarding: punishing someone who wronged us lights up the same reward systems as other pleasures. This is why a half-beaten rival is so dangerous: they carry both the grievance and the motivation. The victor, meanwhile, tends to relax too early, mistaking a pause for an ending.',
    levers: [
      { name: 'Altruistic punishment', text: 'People will pay a personal cost to punish those who wronged them. A defeated enemy may sacrifice a great deal for revenge, which the victor tends to underestimate.' },
      { name: 'Humiliation', text: 'Researchers on conflict describe humiliation as a powerful driver of retaliation and violence, sometimes stronger than material loss. Partial defeat that shames without disabling is the riskiest combination.' },
      { name: 'Zeigarnik effect', text: 'Unfinished tasks stay active in memory more than finished ones. A conflict left unresolved keeps running in the loser’s head and fuels a plan to finish it on their terms.' },
      { name: 'Costly signalling', text: 'A decisive victory sends a message to everyone watching, not just the enemy. Greene’s logic is that thoroughness deters future challengers.' },
    ],
    traps: [
      { id: 'overconfidence', how: 'The winner assumes the beaten rival is finished. The law plays on the opposite fear: that you are overrating your victory.' },
      { id: 'loss-aversion', how: 'The loser feels the defeat more sharply than the winner feels the gain, and will take bigger risks to win it back. That asymmetry is the danger the law warns about.' },
      { id: 'present', how: 'Mercy feels good now and its costs arrive later. The law trades the comfort of the present for safety in the future.' },
    ],
    study: { who: 'Dominique de Quervain and colleagues, 2004', title: 'The sweetness of revenge', text: 'Participants in a PET scanner played a trust game in which a partner could betray them. When betrayed, they could pay to punish the partner. Effective punishment activated the dorsal striatum, a region tied to reward, and people with stronger activation were willing to spend more to punish. Revenge, it seems, is not just a cold calculation: it feels good, which helps explain why a wounded enemy keeps coming back.' },
    today: [
      'A company buying out a struggling competitor rather than letting it recover',
      'Litigation pursued long after the point was won, to deter others',
      'Online pile-ons that aim to end a career, not correct a mistake',
      'Political purges after a leadership contest',
    ],
    scenario: 'After winning a bitter board vote, Elena doesn’t stop at removing her rival from his post. She sees to it that his allies are reassigned, his projects are wound down, and his name disappears from the strategy documents within a month.',
    signs: [
      'A conflict that seemed settled keeps escalating after you’ve conceded',
      'The other side wants not just to win but for you to be gone',
      'Allies of yours are quietly removed one by one',
      'Your apologies or offers of compromise are ignored',
    ],
    defense: [
      'Don’t humiliate people you can’t or won’t remove: it creates the enemy you fear',
      'If you’re the target, keep your support network outside their reach',
      'Document everything when someone seems set on ending you',
      'Look for a third party who benefits from the conflict stopping',
    ],
    shadow: 'Total destruction creates martyrs, sympathy and new enemies among everyone who watched. It can also destroy things you later need, and it rarely ends a conflict between groups, only between individuals. Versailles in 1919 is often cited as a peace harsh enough to breed resentment without removing the threat. Magnanimity, as the rebuilding of Germany and Japan after 1945 showed, can turn an enemy into an ally in a way that crushing never could.',
    honest: 'The honest kernel is about finishing what you start. If a conflict must be fought, resolve it clearly rather than leaving it half-settled, and settle disputes in a way that removes the grievance, not just the opponent.',
    question: 'Is there a conflict in your life that you left half-finished, and is it still running in someone’s head?',
    dark: 9, everyday: 3, kin: [2, 29, 42, 47],
  },

  /* ---------------- 16 ---------------- */
  {
    n: 16, id: 'absence', title: 'Use Absence to Increase Respect and Honour', realm: 'stage',
    line: 'What is always there stops being seen.',
    gist: 'The law says that too much presence cheapens you. Once people have seen and heard enough of you, their respect fades into familiarity. Stepping back, at the right moment, makes them notice the gap you left and wonder what you are doing. Greene argues that scarcity raises value for people as it does for goods, but only if you were valued first.',
    scene: { who: 'Charles de Gaulle', when: '1946–1958', text: 'In January 1946, frustrated by the squabbling of the new Fourth Republic, de Gaulle resigned as head of the provisional government. He tried a political movement, then by the mid-1950s withdrew almost entirely to his home at Colombey-les-Deux-Églises, where he wrote his war memoirs. France’s governments rose and fell in quick succession. When a crisis in Algeria in May 1958 threatened civil war, he was called back, became prime minister, drew up a new constitution and became the first president of the Fifth Republic.' },
    mind: 'The brain pays attention to change and quickly tunes out what stays the same, a process called habituation. Constant presence turns into background. Absence reverses that: it creates a gap, and the mind fills gaps with imagination, which is usually more flattering than reality. Memory also softens with distance, and people remember the best of someone more than the dull middle. Scarcity signals value: if something is hard to get, we assume it must be worth getting. Absence only works, though, if there was something to miss.',
    levers: [
      { name: 'Scarcity heuristic', text: 'Rare things seem more valuable. A person who is hard to reach acquires some of the glow of a scarce good.' },
      { name: 'Habituation', text: 'Repeated stimuli lose their power to command attention. Withdrawal restores the novelty that familiarity wore away.' },
      { name: 'Construal level theory', text: 'Distance, whether in time, space or social terms, makes people think about others more abstractly, in terms of ideals rather than details. From far away, the faults are blurred and the virtues stand out.' },
      { name: 'Mere exposure', text: 'Familiarity breeds liking, up to a point. The law works because exposure first builds attachment, and then absence makes that attachment felt.' },
    ],
    traps: [
      { id: 'rosy', how: 'Memories of someone who has gone grow warmer with time, while their irritations fade. Absence lets rosy retrospection do the work.' },
      { id: 'peak-end', how: 'Leaving on a high point means people remember you by that peak. An exit timed well becomes the image they keep.' },
      { id: 'halo', how: 'Missed people are remembered by their best trait, and that trait colours everything else. Absence strips away the evidence that would complicate the halo.' },
    ],
    study: { who: 'Stephen Worchel, Jerry Lee and Akanbi Adewole, 1975', title: 'The cookie jar', text: 'Participants tasted chocolate chip cookies from a jar holding either ten cookies or two. The same cookies were rated more desirable when there were only two. Most striking, cookies from a jar that had just gone from ten to two were rated highest of all. A sudden loss of availability made the thing itself seem better.' },
    today: [
      'Musicians who vanish between albums and return to bigger crowds',
      'Not replying instantly, so your attention means more when it comes',
      'Stepping away from social media and finding people noticed',
      'A leader who speaks rarely, so every appearance is news',
    ],
    scenario: 'After months of being the one who always organised the group’s plans, Tom goes quiet. He turns down two invitations politely and posts nothing. Within weeks his friends are asking each other what he’s up to and suggesting a dinner in his honour.',
    signs: [
      'Someone who was always available suddenly isn’t, without explanation',
      'You find yourself thinking about them more since they withdrew',
      'Their rare appearances feel like events',
      'Contact comes on their schedule, never yours',
    ],
    defense: [
      'Ask whether you miss the person or the idea of them',
      'Notice when a pattern of withdrawal and return keeps you chasing',
      'Don’t raise your offer just because someone has gone quiet',
      'Value the people who stay present and reliable',
    ],
    shadow: 'Absence is a gamble: if you weren’t valued enough, people simply forget you, and someone else fills the space. In close relationships, strategic withdrawal reads as coldness and teaches the other person not to rely on you. Many leaders who stepped back expecting to be recalled never were. Showing up, steadily and generously, is what builds trust, and trust outlasts mystique.',
    honest: 'Don’t crowd people or overexpose yourself, and leave room for them to want more. Take real breaks, step back when you have nothing to add, and let your work speak while you are away.',
    question: 'Is there someone whose value you only saw when they were gone?',
    dark: 4, everyday: 7, kin: [6, 18, 28],
  },

  /* ---------------- 17 ---------------- */
  {
    n: 17, id: 'unpredictable', title: 'Keep Others in Suspended Terror: Cultivate an Air of Unpredictability', realm: 'war',
    line: 'If they can’t read your next move, they can’t plan their own.',
    gist: 'People cope with others by predicting them. Once your habits are known, opponents can prepare and relax. The law says to break the pattern: act without obvious reason, change course, keep people guessing. Greene argues that unpredictability unsettles others, drains their energy as they try to decode you, and gives you the initiative.',
    scene: { who: 'Bobby Fischer and Boris Spassky', when: 'Reykjavík, 1972', text: 'Fischer arrived late, complained about the cameras, the lighting and the audience, and threatened to leave. He lost the first game, then forfeited the second by not turning up. Two games down, he insisted the third be played in a small back room away from the crowd; Spassky agreed, and lost. Later Fischer opened a game with a move he had almost never played, and won that too. Spassky, the reigning champion, seemed unsettled for much of the match, which Fischer won comfortably.' },
    mind: 'Brains are prediction machines: they constantly forecast what will happen next and track the errors. When the errors keep coming, the system goes on alert, burns energy and floods the body with stress hormones. Uncertainty is often worse than bad news, because bad news can at least be prepared for. People who cannot predict a threat stay vigilant all the time, which is exhausting. And because a confused mind searches hard for patterns, an unpredictable person occupies far more of others’ attention than a predictable one.',
    levers: [
      { name: 'Intermittent reinforcement', text: 'Rewards that come unpredictably produce more persistent behaviour than steady ones. Someone who is warm one day and cold the next keeps others working for their approval.' },
      { name: 'Need for cognitive closure', text: 'People differ in how much they crave a firm answer, but everyone dislikes prolonged ambiguity. Withholding closure keeps others restless and eager to resolve it on your terms.' },
      { name: 'Learned helplessness', text: 'Martin Seligman found that when bad things happen regardless of what animals do, they often stop trying to escape. Unpredictable power can teach people that nothing they do makes a difference.' },
    ],
    traps: [
      { id: 'apophenia', how: 'People keep finding patterns in random behaviour, inventing theories about what the unpredictable person really wants. That busy guessing is exactly what the law aims at.' },
      { id: 'illusion-control', how: 'Targets believe that if they just behave correctly they can avoid the next outburst. The illusion keeps them compliant.' },
      { id: 'negativity', how: 'With no pattern to rely on, people brace for the worst. Negative possibilities loom larger, and the unpredictable person benefits from that dread.' },
    ],
    study: { who: 'Archy de Berker and colleagues, 2016', title: 'Uncertainty is more stressful than certain pain', text: 'Participants played a game in which turning over rocks might reveal a snake, signalling a small electric shock. The researchers tracked how predictable the shocks were. Stress, measured by sweating and pupil size, was highest not when a shock was certain but when it was most uncertain. Knowing something bad is coming was easier to bear than not knowing.' },
    today: [
      'A manager whose moods set the office weather',
      'A partner who blows hot and cold, keeping you hooked',
      'Negotiators who change position without warning to throw the other side',
      'Leaders who issue erratic threats so rivals can’t call their bluff',
    ],
    scenario: 'Ravi’s boss praises a report on Monday and tears apart a similar one on Thursday. He cancels meetings at the last minute and turns up unannounced at others. The team spends half its time trying to guess what kind of day he is having.',
    signs: [
      'You spend a lot of energy trying to read someone’s moods',
      'Rules shift without explanation',
      'You feel relief, not pleasure, when they are pleasant',
      'You’ve stopped proposing things for fear of how they’ll land',
    ],
    defense: [
      'Stop trying to decode: focus on what you can control',
      'Write down the actual pattern; often it is less random than it feels',
      'Set your own steady rules and keep them, whatever their mood',
      'Talk to others in the same position; shared reality reduces the fear',
    ],
    shadow: 'Unpredictability erodes trust, and without trust you can’t build alliances or delegate. People around an erratic leader hide information and avoid risk, so the organisation slows down. In personal life it is a pattern linked to abusive relationships. Being reliable is often far more powerful: people invest in those they can count on.',
    honest: 'Don’t be so predictable that others can exploit you, and keep a little flexibility in how you work. Surprise in creative work or in negotiation is fair. Keep your values and promises steady even while your tactics vary.',
    question: 'Who in your life do you spend energy trying to predict, and what would happen if you stopped?',
    dark: 7, everyday: 5, kin: [3, 25, 48],
  },

  /* ---------------- 18 ---------------- */
  {
    n: 18, id: 'fortress', title: 'Do Not Build Fortresses to Protect Yourself: Isolation Is Dangerous', realm: 'court',
    line: 'The walls that keep enemies out also keep the truth out.',
    gist: 'When threatened, the instinct is to withdraw behind walls: trusted people only, closed doors, controlled information. The law says this is a trap. Isolation cuts you off from news, allies and the subtle signals that warn of danger, while your enemies plot unseen. Greene argues that safety lies in circulation: staying among people, informed and connected.',
    scene: { who: 'Qin Shi Huang, first emperor of China', when: '221–210 BC', text: 'Having unified China, the first emperor grew obsessed with assassins and with living forever. The historian Sima Qian records that he linked his palaces with covered walkways so he could move unseen, and that revealing where he was became a crime. When he died on a tour of the east in 210 BC, his chief minister Li Si and the eunuch Zhao Gao hid the death for weeks. They forged an order that drove the heir, Fusu, to suicide and put a weaker son on the throne. Within four years the dynasty had fallen.' },
    mind: 'Humans are social animals, and our brains treat isolation as a threat. Loneliness raises alertness to danger and makes people read others as more hostile, which drives further withdrawal. Isolated leaders also suffer a quieter problem: the people around them filter what they hear. Bad news travels poorly upward, and a small circle soon tells the leader what they want to hear. The less contact you have with the world, the more your picture of it depends on a few voices, each with their own agenda.',
    levers: [
      { name: 'The mum effect', text: 'People are reluctant to deliver bad news, especially to those with power over them. A walled-off leader receives the edited version of reality.' },
      { name: 'Groupthink', text: 'Irving Janis described how tight, isolated groups suppress dissent and drift into confident mistakes. A fortress is the perfect setting for it.' },
      { name: 'Loneliness and hypervigilance', text: 'John Cacioppo’s work suggests that loneliness pushes the brain into a self-protective mode, more alert to social threats. That fear deepens isolation, which deepens fear.' },
    ],
    traps: [
      { id: 'confirmation', how: 'Inside the fortress, only agreeing voices remain. Every report confirms the ruler’s view, so errors grow unchallenged.' },
      { id: 'overconfidence', how: 'Walls create a feeling of safety that may not be real. The isolated person believes they are secure just when they are most exposed.' },
      { id: 'negativity', how: 'Cut off from ordinary contact, the mind fixes on threats. The law warns that fear of others, fed in isolation, becomes its own danger.' },
    ],
    study: { who: 'Sidney Rosen and Abraham Tesser, 1970', title: 'The mum effect', text: 'Participants were asked to pass on a message to another person about a phone call that carried either good or bad news. They were noticeably more likely to pass on the good news than the bad. Later studies found the reluctance grew when the recipient had power or when the messenger might be blamed. A leader surrounded by subordinates will hear the good news first and the bad news late, if at all.' },
    today: [
      'Executives who only hear from a small inner circle',
      'Working from home and slowly falling out of the loop',
      'Withdrawing from friends after a setback, then feeling more alone',
      'Online echo chambers that feel safe and shut out disagreement',
    ],
    scenario: 'After a messy reorganisation, the founder cuts back to three trusted advisers and stops attending the all-hands meeting. Six months later he is the last to hear that two key teams are planning to leave together.',
    signs: [
      'You’ve stopped hearing anything that surprises you',
      'Your circle has shrunk to people who depend on you',
      'News reaches you late and second-hand',
      'You feel safer the less you go out, but more anxious too',
    ],
    defense: [
      'Keep regular contact with people who don’t need anything from you',
      'Ask for bad news explicitly and thank people who bring it',
      'Go to the places where real work happens',
      'When afraid, move towards people rather than away',
    ],
    shadow: 'Being too open has its costs too: constant exposure leaves no time to think, and some secrets really do need keeping. People sometimes need retreat to recover from loss or burnout. The real distinction is between a temporary refuge and a permanent wall. Solitude for reflection, with ties kept alive, is very different from a siege mentality.',
    honest: 'Stay connected: keep a wide network, listen to people at every level and invite dissent. It isn’t a strategy for power so much as a defence against your own blind spots.',
    question: 'Who would tell you if you were making a serious mistake, and when did they last do it?',
    dark: 2, everyday: 6, kin: [16, 20, 24],
  },

  /* ---------------- 19 ---------------- */
  {
    n: 19, id: 'wrong-person', title: 'Know Who You’re Dealing With: Do Not Offend the Wrong Person', realm: 'court',
    line: 'Before you push, find out who pushes back.',
    gist: 'People react differently to the same slight. Some shrug it off, some brood for years, some are proud and vindictive, and some are far stronger than they look. The law says that before you deceive, insult or cross someone, you must know what kind of person they are. Greene’s point is that misjudging character is one of the commonest causes of downfall, because a single offence to the wrong person can follow you for life.',
    scene: { who: 'Julius Caesar and the Cilician pirates', when: 'c. 75 BC', text: 'As a young man sailing to Rhodes, Caesar was captured by pirates who asked a ransom of twenty talents. Plutarch says he laughed and told them he was worth at least fifty. While his companions raised the money, he spent over a month with them, joining their games, reading them his speeches and poems, and joking that he would crucify them all. Once released, he raised ships, hunted them down and did exactly that. They had taken him for a rich young man to be squeezed, not someone who would keep his word.' },
    mind: 'We form impressions of others astonishingly fast, from a face, a voice, a few gestures. These snap judgements are partly accurate but leave out a lot: pride, memory for grievance, hidden resources. People also differ widely in how they handle insult. For some, an affront to honour is an emergency that demands a response. For others, a perceived wound to their self-image triggers lasting hostility. Treating everyone as if they’ll react as you would is the root of the mistake.',
    levers: [
      { name: 'Culture of honour', text: 'In some cultures and personalities, reputation for toughness is everything, and insult demands retaliation. Offending such a person costs far more than offending someone who shrugs.' },
      { name: 'Thin-slicing', text: 'Nalini Ambady showed that people make quick judgements from brief glimpses, sometimes surprisingly accurate ones. But thin slices miss hidden traits like vindictiveness and resolve.' },
      { name: 'Threatened egotism', text: 'Roy Baumeister and Brad Bushman found that people with inflated, fragile self-views are the most likely to lash out when criticised. Big egos, wounded, make dangerous enemies.' },
    ],
    traps: [
      { id: 'fae', how: 'We read someone’s quietness or politeness as their character, not their situation. The meek clerk may simply be biding time.' },
      { id: 'halo', how: 'A friendly manner can hide a long memory, and a modest appearance can hide great power. One surface trait shapes your whole guess about how they’ll react.' },
      { id: 'projection', how: 'You assume others will take a joke or a slight the way you would. The law warns that their reaction is theirs, not yours.' },
      { id: 'overconfidence', how: 'We trust our first reads of people far more than their accuracy warrants, which leads us to take risks with the wrong person.' },
    ],
    study: { who: 'Dov Cohen, Richard Nisbett and colleagues, 1996', title: 'The insult in the hallway', text: 'At the University of Michigan, male students walking down a narrow corridor were bumped by a confederate who muttered an insult. Those raised in the American South, with its tradition of honour culture, became more upset, showed bigger rises in cortisol and testosterone, and acted more aggressively afterwards than those from the North. The same insult produced very different reactions depending on who received it.' },
    today: [
      'Mocking a junior colleague who later becomes your manager',
      'Picking a fight online with someone who has a large, loyal following',
      'Underestimating a quiet relative who never forgets a slight',
      'Dismissing a customer who turns out to know the owner',
    ],
    scenario: 'At a networking event, Josh brushes off a soft-spoken woman in a plain jacket to talk to someone more senior. Two months later she chairs the panel deciding on his company’s funding.',
    signs: [
      'You’ve made assumptions about someone’s power from their manner or dress',
      'Someone’s reaction to a small slight seems out of proportion',
      'People who know them warn you to be careful',
      'They are calm in public but keep careful track of who said what',
    ],
    defense: [
      'Treat everyone with basic respect: it costs little and protects a lot',
      'Ask around before crossing someone you don’t know well',
      'Repair offences quickly and sincerely',
      'Watch how people respond to small frictions before risking big ones',
    ],
    shadow: 'Too much caution can make you timid, endlessly calculating whom you can afford to offend. It can also make you treat people differently according to their power, which others notice and dislike. Sometimes the right thing is to stand up to the powerful, knowing the cost. The real lesson is not fear of the strong but respect for everyone.',
    honest: 'Pay attention to people as individuals: their pride, their history, their sensitivities. Treat everyone with courtesy, not because they might strike back but because people are more than they appear.',
    question: 'Whom have you underestimated, and what did it cost you?',
    dark: 3, everyday: 8, kin: [15, 24, 38],
  },

  /* ---------------- 20 ---------------- */
  {
    n: 20, id: 'commit', title: 'Do Not Commit to Anyone', realm: 'court',
    line: 'Stay courted and you stay powerful.',
    gist: 'Every side wants you on its team, and the moment you join, your value drops. The law says to keep your independence: let others court you, take part where it suits you, but don’t bind yourself to any faction. Once committed, you inherit their enemies and lose your leverage. Greene argues that the free agent, sought by all, holds more power than any loyal partisan.',
    scene: { who: 'Elizabeth I of England', when: '1559–1581', text: 'From the start of her reign, Elizabeth was pressed to marry, and suitors came from Spain, Sweden, Austria and France. She encouraged several, sometimes for years, without accepting any. Her long courtship with Francis, Duke of Anjou, kept France friendly at a time when England needed it against Spain. In 1581, by several accounts, she publicly kissed him and gave him a ring, then backed away within days. She never married, and kept every power guessing.' },
    mind: 'People value what they cannot quite have. Uncertainty keeps attention fixed, while a settled outcome lets the mind move on. Courtship also generates investment: each suitor puts in time, gifts and hope, and the more they invest the harder it is to walk away. Meanwhile, the courted party collects attention and offers from everyone. Commitment closes that market. And once committed, you are bound by consistency: people expect you to stand by your choice, so changing sides becomes costly.',
    levers: [
      { name: 'Uncertainty and attraction', text: 'Not knowing whether someone favours you keeps them on your mind and can raise their appeal. The undecided party holds attention that a committed one would lose.' },
      { name: 'Commitment and consistency', text: 'Robert Cialdini described how once people commit, they feel pressure to act consistently with that choice. Avoiding commitment avoids that pressure.' },
      { name: 'Best alternative to a negotiated agreement', text: 'Negotiation theory says your power depends on your alternatives. Staying unattached keeps all your alternatives open.' },
    ],
    traps: [
      { id: 'sunk-cost', how: 'Each side keeps investing in winning the uncommitted party, and the more they spend the harder it is to quit. The courted party lives off that spending.' },
      { id: 'optimism', how: 'Every suitor believes they are close to winning. The uncommitted party feeds that hope without fulfilling it.' },
      { id: 'conformity', how: 'When everyone else wants someone, you want them too. Being widely courted is itself a signal of value.' },
    ],
    study: { who: 'Erin Whitchurch, Timothy Wilson and Daniel Gilbert, 2011', title: 'He loves me, he loves me not', text: 'Female students viewed the profiles of men who had supposedly seen their own profiles. Some were told the men liked them a lot, some that they liked them an average amount, and some that it was uncertain. The women were most attracted to the men whose feelings were uncertain, and reported thinking about them the most. Not knowing kept them engaged.' },
    today: [
      'Juggling job offers to raise your price',
      'Keeping two romantic interests in play without choosing',
      'A swing voter or swing state courted by every campaign',
      'A consultant who works for all sides of an industry',
    ],
    scenario: 'Asha has offers from two start-ups and her current employer. She tells each that she’s very interested but needs a little more time, and over three weeks each improves its offer twice.',
    signs: [
      'Someone keeps you investing without ever committing back',
      'You hear hints that others are courting them too',
      'Every step forward is followed by “not yet”',
      'You feel lucky to have their attention',
    ],
    defense: [
      'Set a deadline and stick to it',
      'Count what you’ve invested and ask whether it’s returning anything',
      'Make your own alternatives real, not imaginary',
      'Value people who choose you clearly',
    ],
    shadow: 'Endless non-commitment leaves you with no allies when you need them. People see the game, and the uncommitted become trusted by nobody. In love and friendship, refusing to commit means missing what only commitment gives: depth, security, being known. Sometimes picking a side, and staying, is the most powerful move.',
    honest: 'Don’t rush into commitments under pressure, and keep the independence to judge each case. But when you commit, mean it, and be honest about where you stand rather than stringing people along.',
    question: 'Where are you keeping options open, and what is it costing the people waiting on you?',
    dark: 6, everyday: 7, kin: [2, 16, 18],
  },

  /* ---------------- 21 ---------------- */
  {
    n: 21, id: 'sucker', title: 'Play a Sucker to Catch a Sucker: Seem Dumber Than Your Mark', realm: 'mask',
    line: 'Nobody guards against the person they think is a fool.',
    gist: 'People like to feel smarter than those around them, and they relax around anyone who seems less clever. The law says to use that: appear slower, simpler or more naive than you are, and others will underestimate you and drop their guard. Greene argues that seeming harmless is the best disguise, because nobody plots against the fool.',
    scene: { who: 'Claudius, later Roman emperor', when: 'AD 37–41', text: 'Claudius limped, stammered and was mocked by his own family as a simpleton. Under his nephew Caligula, who murdered relatives and rivals freely, he was humiliated at court but left alive. The historian Suetonius reports that Claudius later claimed he had exaggerated his foolishness on purpose, to survive. When Caligula was assassinated in AD 41, soldiers found Claudius hiding behind a curtain in the palace and proclaimed him emperor. He ruled for thirteen years.' },
    mind: 'Being outshone is uncomfortable, and people protect their sense of competence by comparing themselves with others. Someone who seems less able is no threat to that sense, so we feel at ease, a little superior and inclined to like them. We also judge people quickly and then stop checking. Once someone is filed as harmless, information that contradicts that view is overlooked. That lets the apparently dim person watch, learn and act with very little suspicion.',
    levers: [
      { name: 'Pratfall effect', text: 'Elliot Aronson found that a competent person who makes a small blunder becomes more likeable. Small signs of fallibility lower people’s defences.' },
      { name: 'Self-evaluation maintenance', text: 'Abraham Tesser’s model holds that people feel threatened when someone close outperforms them in an area they care about. Seeming less able keeps you clear of that threat.' },
      { name: 'Downward social comparison', text: 'Comparing ourselves with someone less able boosts our mood and confidence. The mark enjoys the comparison and stops looking closely.' },
    ],
    traps: [
      { id: 'overconfidence', how: 'The mark trusts their own judgement too much and assumes they have read the situation. Seeming dumber feeds that overconfidence.' },
      { id: 'dunning-kruger', how: 'People often misjudge competence, their own and others’. The law relies on the mark being confident about who in the room is clever.' },
      { id: 'halo', how: 'One clumsy trait, such as a stammer or a naive question, is taken to mean incompetence across the board. A reverse halo hides the person’s real ability.' },
    ],
    study: { who: 'Elliot Aronson, Ben Willerman and Joanne Floyd, 1966', title: 'The pratfall effect', text: 'Students listened to a recording of a quiz contestant who was either highly competent or mediocre. In some versions, the contestant spilled a cup of coffee at the end. The highly competent contestant who spilled the coffee was rated more likeable than the one who didn’t, while the mediocre contestant who spilled became less likeable. A small sign of fallibility made an impressive person easier to like.' },
    today: [
      'The detective-style “sorry, just one more question”',
      'A negotiator who asks naive questions to draw out the other side',
      'A new hire who plays it modest while learning how things really work',
      'Scammers who pretend not to understand, so you explain too much',
    ],
    scenario: 'In the negotiation, Paolo keeps asking for things to be explained again, apologising that numbers aren’t his strong point. The other side, growing confident, walks him through their margins in detail to show how generous their offer is.',
    signs: [
      'Someone asks questions that seem too basic for their role',
      'You find yourself explaining far more than you meant to',
      'They seem harmless, yet things keep going their way',
      'You feel a pleasant superiority in their company',
    ],
    defense: [
      'Judge people by their results, not their manner',
      'Answer basic questions briefly and see whether they really need more',
      'Ask yourself why you feel so relaxed with this person',
      'Assume competence until proven otherwise',
    ],
    shadow: 'Playing dumb can stick: people may come to believe it and pass you over for real opportunities. It can also feel dishonest to yourself and erode self-respect. Constantly hiding your ability means people never see your real value. In a fair setting, showing competence openly is usually more rewarding.',
    honest: 'Humility is a strength: asking questions, admitting what you don’t know and not showing off. Let others feel capable, and learn by listening, while staying honest about who you are.',
    question: 'When did you last underestimate someone because of how they seemed?',
    dark: 6, everyday: 6, kin: [1, 3, 22, 38],
  },

  /* ---------------- 22 ---------------- */
  {
    n: 22, id: 'surrender', title: 'Use the Surrender Tactic: Transform Weakness into Power', realm: 'long',
    line: 'Bend now, so you’re still standing later.',
    gist: 'When you are weaker, fighting back for honour only gets you crushed. The law says to surrender instead: yield, comply, even flatter, and buy time. Surrender disarms the victor, who relaxes, while you recover, watch and wait. Greene argues that apparent submission can be a strategy, turning weakness into a route to eventual power.',
    scene: { who: 'Bertolt Brecht and the House Un-American Activities Committee', when: 'October 1947', text: 'The German playwright Brecht, a Marxist living in Hollywood, was called before the committee investigating communists. Other writers summoned with him refused to answer and attacked the committee; ten of them were later jailed for contempt. Brecht answered politely, used an interpreter, and denied being a party member. The chairman thanked him and called him a good example to the other witnesses. The next day he flew to Europe, where he went on to found a celebrated theatre company in East Berlin.' },
    mind: 'Conflict escalates when each side meets force with force. A display of submission tends to switch off aggression, in animals and in people, because it signals that the threat is over. Victors also relax quickly: once they feel they have won, they stop watching closely. And concessions create pressure to reciprocate, so yielding on one point can win something on another. The person who surrenders gives up the fight, not the long game.',
    levers: [
      { name: 'Appeasement displays', text: 'Dacher Keltner and others have described how embarrassment, bowed posture and apology work as appeasement signals that reduce others’ aggression. Submission can calm a threat faster than defiance.' },
      { name: 'Reciprocity of concessions', text: 'When one party backs down, the other feels pressure to give something back. Yielding can draw out a concession that fighting never would.' },
      { name: 'Reactance', text: 'Jack Brehm showed that people push back when their freedom is threatened. Resistance provokes a stronger counter-attack; surrender removes the provocation.' },
    ],
    traps: [
      { id: 'overconfidence', how: 'The victor, having seen the opponent submit, assumes the matter is settled. Their attention moves on, which gives the surrendering party room.' },
      { id: 'self-serving', how: 'The stronger side reads the surrender as proof of its own strength and rightness, not as tactics, so it doesn’t look for what the weaker side is planning.' },
      { id: 'present', how: 'An immediate win feels decisive. The victor discounts what the loser may do later, once the moment has passed.' },
    ],
    study: { who: 'Robert Cialdini and colleagues, 1975', title: 'The door in the face', text: 'Students on a campus were asked to volunteer to chaperone a group of young offenders on a day trip to the zoo. Asked straight out, only a small minority agreed. But when the same request followed a much larger one, which nearly everyone refused, about three times as many agreed. The retreat from a big request to a smaller one felt like a concession, and people reciprocated.' },
    today: [
      'Apologising in a meeting to defuse a confrontation, then quietly fixing the problem your way',
      'A small company accepting a large rival’s terms to survive and grow',
      'Conceding a minor point in an argument to win the larger one',
      'Complying with an unreasonable boss while preparing to leave',
    ],
    scenario: 'When the director publicly criticises her plan, Leah doesn’t argue. She thanks him for the feedback, agrees to his changes and asks for his advice. Three months later his approach has stalled, and he invites her to lead the revised version.',
    signs: [
      'An opponent gives way unusually easily after a hard fight',
      'Their compliance is perfect but their effort is minimal',
      'They ask for your advice while keeping their own counsel',
      'You feel generous towards someone you were fighting yesterday',
    ],
    defense: [
      'Don’t treat compliance as agreement: check what actually changes',
      'Stay curious about what the yielding party still wants',
      'Make settlements fair, so surrender isn’t a cover for resentment',
      'Watch actions over the following months, not words in the moment',
    ],
    shadow: 'Surrender can become a habit, and some people yield so often that they lose the ability to resist when it matters. It can also look like collaboration with injustice. There are moments when standing firm, at real cost, is the only decent thing to do, and history remembers those who did. Strategic retreat is wise; endless retreat is defeat.',
    honest: 'Not every fight needs to be fought now. Choose your battles, de-escalate when you can, and admit when you’re outmatched, while keeping your values and goals intact.',
    question: 'Is there a fight you are losing that you could step out of, for now, without giving up what matters?',
    dark: 5, everyday: 6, kin: [15, 21, 29, 48],
  },

  /* ---------------- 23 ---------------- */
  {
    n: 23, id: 'concentrate', title: 'Concentrate Your Forces', realm: 'war',
    line: 'Ten scattered efforts lose to one focused one.',
    gist: 'Spread yourself across too many goals, allies or projects and you dilute your strength. The law says to concentrate: put your energy, money and attention where they count, and drop the rest. A narrow, deep effort beats a broad, shallow one. Greene argues that intensity, not extent, wins: one strong source of power is worth more than many weak ones.',
    scene: { who: 'Steve Jobs at Apple', when: '1997–1998', text: 'When Jobs returned to Apple in 1997, the company was close to bankruptcy and selling a confusing range of computers and devices. According to his biographer Walter Isaacson, he drew a simple grid in a product meeting: consumer and professional, desktop and portable. Apple would make one great product for each box, and nothing else. Most of the line was cut, including the Newton handheld. The focused range, starting with the iMac in 1998, helped bring the company back to profit.' },
    mind: 'Attention is limited. Each switch between tasks has a cost, and part of the mind stays stuck on what you left. Spreading effort also spreads commitment, so no project gets the persistence it needs to break through. Focus has a psychological benefit too: a single clear goal is easier to stick to, and progress on it feels motivating. People and organisations that try to do everything usually end up doing nothing well.',
    levers: [
      { name: 'Attention residue', text: 'Sophie Leroy found that after switching tasks, part of our attention lingers on the previous one, lowering performance on the next. Fewer fronts mean less residue.' },
      { name: 'Task-switching costs', text: 'Experiments on task switching show measurable losses in speed and accuracy each time people change tasks. Concentrated effort avoids paying that toll.' },
      { name: 'Goal shielding', text: 'James Shah and colleagues found that focusing on one goal can suppress competing goals, helping people stick with it. Too many goals weaken that protection.' },
      { name: 'Choice overload', text: 'Too many options can paralyse decisions and reduce satisfaction. A narrow focus also makes choices clearer for those you serve.' },
    ],
    traps: [
      { id: 'planning', how: 'People underestimate how long each project will take, so they take on too many at once. The law corrects for that optimism by forcing focus.' },
      { id: 'sunk-cost', how: 'Scattered projects survive because of what has already gone into them. Concentrating means cutting things you have invested in.' },
      { id: 'overconfidence', how: 'We believe we can juggle more than we can. Concentration is a guard against the belief that you are the exception.' },
    ],
    study: { who: 'Eyal Ophir, Clifford Nass and Anthony Wagner, 2009', title: 'The cost of media multitasking', text: 'Stanford researchers compared heavy and light media multitaskers on a series of attention tasks. The heavy multitaskers were worse at filtering out irrelevant information and, surprisingly, worse at switching between tasks. People who habitually spread their attention seemed less able to focus it when needed.' },
    today: [
      'A start-up that does one thing well instead of five things badly',
      'Turning off notifications to do deep work',
      'Investing heavily in one key relationship at work',
      'A campaign that focuses on a single message',
    ],
    scenario: 'The new director scraps eleven of the department’s fourteen initiatives in her first week. She puts the whole team on the three that remain and spends every meeting on their progress.',
    signs: [
      'You are busy all the time and finishing very little',
      'Your projects compete for the same scarce resources',
      'You can’t say which goal matters most',
      'You hesitate to drop anything because you’ve already started',
    ],
    defense: [
      'Name your one or two priorities and protect them',
      'Kill weak projects deliberately rather than letting them linger',
      'Batch similar work to cut switching',
      'Watch for people who distract you on purpose',
    ],
    shadow: 'Concentration is risky: if your one bet fails, you have nothing to fall back on. Diversification protects against shocks, in investment and in life. Too narrow a focus can also blind you to change, and to opportunities outside your chosen path. The skill lies in knowing when to concentrate and when to spread.',
    honest: 'Choose what matters most and give it your best, rather than scattering yourself. Saying no to good things is how you say yes to the important ones.',
    question: 'If you could only do one thing well this year, what would it be?',
    dark: 2, everyday: 8, kin: [29, 42, 47],
  },

  /* ---------------- 24 ---------------- */
  {
    n: 24, id: 'courtier', title: 'Play the Perfect Courtier', realm: 'court',
    line: 'Near power, every gesture is watched, so make each one graceful.',
    gist: 'Wherever there is power, there is a court: people competing for the favour of those at the top. The law says to master its arts: flatter with tact, never outshine the master, stay modest and graceful, read the mood and adapt. A courtier thrives by making things easy and pleasant for those in charge, without seeming to try. Greene argues that this social skill is a form of power in itself.',
    scene: { who: 'Alexander the Great and Callisthenes', when: '327 BC', text: 'As Alexander’s conquests grew, he began asking his Greek and Macedonian companions to adopt the Persian custom of bowing before the king. His court historian, Callisthenes, refused openly. Plutarch tells how, at a banquet, Callisthenes skipped the bow, and when he was denied the king’s kiss remarked that he was leaving the poorer by a kiss. Soon afterwards he was accused of involvement in a plot by royal pages and died in custody, though accounts of how differ. His principle may have been sound, but his handling of the court cost him his life.' },
    mind: 'Hierarchies are ancient, and humans are tuned to the status signals of those above them. People in power like to feel admired and secure, and they reward those who make them feel so. Flattery works even when we half know it’s flattery, because we want to believe it. Yet people also watch how someone treats those below them, and a reputation for fawning upward while bullying downward can turn sour. A good courtier manages this balance with grace, which is why the art is so hard.',
    levers: [
      { name: 'Ingratiation', text: 'Studies of ingratiation find that flattery and agreement generally make people like you more, even when the target suspects them. The courtier uses it with care.' },
      { name: 'Impression management', text: 'Erving Goffman described social life as a performance in which people manage how they come across. The court is a stage where the performance never stops.' },
      { name: 'Self-evaluation maintenance', text: 'Those above us dislike being outperformed in areas they care about. The courtier lets the master shine.' },
    ],
    traps: [
      { id: 'halo', how: 'A pleasant, graceful manner spreads into judgements of competence and loyalty. The courtier’s charm vouches for everything else.' },
      { id: 'self-serving', how: 'Leaders accept praise as an accurate reflection of their abilities. Flattery works because it agrees with what they already want to believe.' },
      { id: 'authority', how: 'People near the top defer to rank, and courtiers learn to channel that deference smoothly, gaining influence by seeming to give it away.' },
    ],
    study: { who: 'Roos Vonk, 1998', title: 'The slime effect', text: 'Participants read descriptions of people who behaved either likeably or unpleasantly towards superiors and towards subordinates. Those who were pleasant to superiors but nasty to subordinates were rated especially negatively, more than people who were unpleasant to everyone. Observers called them slimy. Flattery that only flows upward is noticed and disliked by everyone watching.' },
    today: [
      'Praising a boss’s idea in front of others, then quietly improving it',
      'Learning the unspoken rules of a new workplace before speaking up',
      'Keeping your best ideas from outshining your manager’s in public',
      'Building goodwill with gatekeepers like assistants and receptionists',
    ],
    scenario: 'Nadia notices her manager hates being contradicted in meetings, so she raises concerns with him privately afterwards and lets him present the fixes as his own. She is friendly with his assistant and never talks about her own wins unless asked.',
    signs: [
      'Someone agrees with everything you say',
      'Praise arrives at exactly the right moments',
      'They treat you very differently from how they treat those below them',
      'You feel unusually wise in their company',
    ],
    defense: [
      'Reward people who disagree with you openly',
      'Watch how someone treats those with no power over them',
      'Ask flatterers for specific criticism',
      'Keep your judgement separate from how good someone makes you feel',
    ],
    shadow: 'The perfect courtier can lose themselves in the role, becoming only a mirror for others. Constant flattery corrodes honest feedback, and the leader surrounded by courtiers walks into disaster. Those who see a courtier fawning above and sneering below distrust them. Sometimes speaking truth to power, cleanly and respectfully, earns more lasting respect than grace.',
    honest: 'Learn the culture you work in, be courteous to everyone, and give credit generously. Say what you think, choosing your moment and your words with care.',
    question: 'Whom do you treat differently because of their power, and would you be comfortable if everyone saw it?',
    dark: 4, everyday: 8, kin: [1, 4, 19, 46],
  },
];
